/* 星港 — culture_v31.js：v3.1 殖民地文化系统（约 12000 行）
 * 接入函数：CultureV31Integration.attach(game) —— 挂 game.cultureV31，
 *   game.cultureV31Tick(game, now, dt) / game.cultureV31Modifiers() 亦由 attach 挂载。
 * 依赖（全部防御性读取，缺失时降级为内部默认值，不崩溃）：
 *   game.pop.count（人口）/ game.builder.buildings（[{id, level|lv}]）/ game.player.inv
 *   （iron/ice/rare/water/food/steel/tech/uranium/he3）/ game.policy（政策）/
 *   game.tech（科技倍率）/ game.economy（幸福度/星币，可选）/ game.city（可选）。
 *   只读引用现有全局名：TERRAIN / Population / TUTORIAL_STEPS / DS_TUNE /
 *   OVERLAY_MODES / BUILDINGS / RES_VALUE 等一律不重声明、不赋值，仅 typeof 守卫读取。
 * 数据规模：文化五系 × 10 级（50 级定义）/ 文化建筑映射 110 座 / 文化政策 40 条 /
 *   文化作品 200 件（画作/乐曲/小说/赛事各 50）/ 节日 36 个 / 展览场馆 24 座 /
 *   文化名人 110 位 / 文化冲突事件 54 起（每起 3 个抉择）/ 品质评级 7 档 / 主题展览 48 个 /
 *   文化里程碑 100 个 / 五系协同 10 条 / 巡展路线 24 条 / 作品联动 120 组 /
 *   观众群体 20 类 / 名人专场 60 场 / 冲突余波 54 条 / 场馆节目单 48 期。
 * 核心公式（实现见 CultureV31Calculator，数值由本生成器实算并写入各条目注释）：
 *   文化值 V = Σ系 Vb，Vb = raw_b × (1 − 0.35 × raw_b / (raw_b + 400))（边际递减）；
 *   raw_b = 建筑贡献 + 政策贡献 + 作品常驻 + 名人加成 + 节日进行中加成；
 *   满意度加成 = min(25, 0.06 × V) 点；移民吸引力 = 1 + min(0.60, V / 500)；
 *   人口增长修正 = 1 + 0.02 × 五系平均等级 + 0.10 × (吸引力 − 1)；
 *   作品收益 = 基础价 × 品质倍率 × (1 + 名气/100) × 展览倍率；
 *   节日净收益 = 全城加成持续天数 × 日均文化产出折算 − 筹办花费。
 * 生成方式：/tmp/gen_culture_v31.py（数据表 + 实算模板）；数值注释全部由生成器实算。
 * 本文件只新增 culture_v31.js，不修改 game.js / index.html / 其他任何文件。
 */
'use strict';

/* ============================== CULT31 常量 ============================== */
const CULT31_VERSION = '3.1.0';
const CULT31_BRANCH_IDS = ['art', 'music', 'literature', 'sports', 'festival'];
const CULT31_BRANCH_NAMES = { art: '艺术', music: '音乐', literature: '文学', sports: '体育', festival: '节日' };
const CULT31_BRANCH_ICONS = { art: '🎨', music: '🎵', literature: '📖', sports: '🏟️', festival: '🎉' };
const CULT31_MAX_LEVEL = 10;
const CULT31_DIMINISH_K = 400;
const CULT31_DIMINISH_MAX = 0.35;
const CULT31_SAT_PER_CULTURE = 0.06;
const CULT31_SAT_CAP = 25;
const CULT31_IMMIGRATION_PER_CULTURE = 1 / 500;
const CULT31_IMMIGRATION_CAP = 0.60;
const CULT31_GROWTH_PER_AVG_LEVEL = 0.02;
const CULT31_TICK_MS = 1000;
const CULT31_FESTIVAL_PREP_DAYS = 3;
const CULT31_WORK_SLOTS_BASE = 4;
const CULT31_CELEB_SALARY_BASE = 12;
const CULT31_QUALITY_TIERS = ['粗糙', '平庸', '合格', '优秀', '精湛', '大师', '传世'];
const CULT31_QUALITY_MUL = [0.4, 0.7, 1.0, 1.5, 2.2, 3.2, 5.0];
const CULT31_QUALITY_MIN_SCORE = [0, 20, 40, 55, 70, 85, 95];
const CULT31_FAME_DECAY_PER_DAY = 0.5;
const CULT31_XP_PER_MIN_BASE = 1.0;

/* 升级所需累计经验：need(L) = round(80 × L^1.7)；L 为目标等级（1..10）。
 * L1 80 / L2 260 / L3 518 / L4 845 / L5 1235 / L6 1683 / L7 2187 / L8 2744 / L9 3351 / L10 4009。
 * 五系满级累计经验 = 16912 点/系，全系满级 = 84560 点。
 * 每级文化产出（culture/min）：2.0 × L^1.25；满级单系 35.6/分钟，五系满级 178/分钟。
 * 每级满意度：0.8 × L；满级单系 +8.0 点，五系满级 +40 点（受 CULT31_SAT_CAP 上限 25 约束）。
 * 每级移民吸引力：0.02 × L；满级单系 +0.20，五系满级 +1.00（受上限 0.60 约束）。
 */
function cult31XpNeedV31(level) {
  if (level < 1) return 0;
  if (level > CULT31_MAX_LEVEL) level = CULT31_MAX_LEVEL;
  return Math.round(80 * Math.pow(level, 1.7));
}
function cult31LevelOutputV31(level) {
  if (level <= 0) return 0;
  return Math.round(2.0 * Math.pow(level, 1.25) * 100) / 100;
}

