/* 每座建筑按主系归属给文化贡献：base（L1 每分钟文化值）× 等级系数（L2 1.8× / L3 3.0×）。
 * 归属规则：图书馆/美术馆类 → 艺术或文学高贡献；体育场/训练场 → 体育；广场/纪念馆 → 节日；
 * 音乐厅类缺省时由广播/宣传类建筑兼任音乐；其余生产建筑给少量节日/艺术氛围值（0.1~0.6）。
 * 全城建筑文化 raw = Σ base × lvMul × (1 + 0.05 × 同系建筑数，上限 +50%)（集聚加成，见计算器）。
 * 110 座满配 L3 理论 raw 约 640 点/分钟，递减后单系价值约 380 点，仍在公式有效区间内。
 */
