    // [期望] 两件均价 200 星币作品联动展览一次，额外收益约 136 星币。
    // [高价] 两件均价 500 星币作品联动一次，额外收益约 340 星币；回本需联动展览 1 次（按策划成本 100 计）。
    // [叠加] 联动倍率 × 场馆倍率 × 主题展览倍率三者叠乘；理论上限 1.50 × 2.40 × 2.20 ≈ 7.92×。
    // [条件] 两件均已创作且均在展出；任一撤展即失效；可与场馆满展倍率叠乘。
