/* 观众群体决定展览收益结构：每类有偏好系、规模占比、消费倍率、满意度权重。
 * 展览收益修正 = Σ(占比 × 该系偏好时 1.2，否则 0.9) × 消费倍率；满意度 = Σ(占比 × 权重)。
 */
