/* ============================== CULT31 工具函数 ============================== */
/* 全部纯函数、无外部依赖；确定性随机用 mulberry32（种子固定可复现）。 */
function cult31ClampV31(x, lo, hi) {
  if (!isFinite(x)) return lo;
  return x < lo ? lo : (x > hi ? hi : x);
}
function cult31Round2V31(x) { return Math.round((isFinite(x) ? x : 0) * 100) / 100; }
function cult31SafeNumV31(x, defVal) {
  const n = Number(x);
  return isFinite(n) ? n : (defVal === undefined ? 0 : defVal);
}
function cult31MulberryV31(seed) {
  // mulberry32：确定性伪随机，同一-seed 同一序列，用于作品评分与冲突检定。
  let a = seed >>> 0;
  return function cult31NextV31() {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function cult31DeepCloneV31(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(function (v) { return cult31DeepCloneV31(v); });
  const out = {};
  for (const k in obj) if (Object.prototype.hasOwnProperty.call(obj, k)) out[k] = cult31DeepCloneV31(obj[k]);
  return out;
}
function cult31QualityTierOfV31(score) {
  // 评分 → 档位：0/20/40/55/70/85/95 七档；score 越界时夹取。
  const s = cult31ClampV31(score, 0, 100);
  let tier = 0;
  for (let i = 0; i < CULT31_QUALITY_MIN_SCORE.length; i++) {
    if (s >= CULT31_QUALITY_MIN_SCORE[i]) tier = i;
  }
  return tier;
}
function cult31QualityNameV31(score) { return CULT31_QUALITY_TIERS[cult31QualityTierOfV31(score)]; }
function cult31QualityMulOfV31(score) { return CULT31_QUALITY_MUL[cult31QualityTierOfV31(score)]; }

/* ============================== CultureV31Calculator：纯公式计算器 ============================== */
/* 本类不读 game、不写状态：所有方法输入数字/快照、输出数字，可单独单元测试。 */
/* 公式总表（与文件头一致，数值全部可由本类复算）： */
/*   (1) 递减：diminish(raw) = raw × (1 − 0.35 × raw / (raw + 400)) */
/*   (2) 系经验 → 等级：levelFromXp(xp) 按 cult31XpNeedV31 累计表反查 */
/*   (3) 满意度：sat = min(25, 0.06 × V) + Σ政策 satAdd + 节日进行中 bonusSat */
/*   (4) 移民：imm = 1 + min(0.60, V / 500) + Σ政策 immAdd + 节日 bonusImm */
/*   (5) 人口增长：growth = 1 + 0.02 × 平均等级 + 0.10 × (imm − 1) */
/*   (6) 作品收益：rev = basePrice × 品质倍率 × (1 + fame/100) × exhibitMul */
/*   (7) 作品评分：score = baseScore + 系等级 × 3 + 名人 teachMul × 100 × 0.5 + 随机 ±5 */
class CultureV31Calculator {
  static diminishV31(raw) {
    // 边际递减：raw=0→0；raw=100→93.0；raw=400→330.0；raw=1000→750.0；raw→∞ 渐近 0.65×raw。
    const r = Math.max(0, cult31SafeNumV31(raw, 0));
    if (r === 0) return 0;
    return cult31Round2V31(r * (1 - CULT31_DIMINISH_MAX * r / (r + CULT31_DIMINISH_K)));
  }
  static levelFromXpV31(xp) {
    // 按累计经验反查等级：累计 need(1..L) 之和；xp 超过满级累计时返回 10。
    let total = 0; let level = 0;
    for (let lv = 1; lv <= CULT31_MAX_LEVEL; lv++) {
      total += cult31XpNeedV31(lv);
      if (xp >= total) level = lv; else break;
    }
    return level;
  }
  static xpToNextV31(xp) {
    // 距下一级还差多少经验；满级返回 0。
    let total = 0;
    for (let lv = 1; lv <= CULT31_MAX_LEVEL; lv++) {
      total += cult31XpNeedV31(lv);
      if (xp < total) return total - xp;
    }
    return 0;
  }
  static xpProgressV31(xp) {
    // 本级进度 0..1：(xp − 上级累计) / need(本级+1)。
    const lv = CultureV31Calculator.levelFromXpV31(xp);
    if (lv >= CULT31_MAX_LEVEL) return 1;
    let prev = 0;
    for (let k = 1; k <= lv; k++) prev += cult31XpNeedV31(k);
    return cult31ClampV31((xp - prev) / cult31XpNeedV31(lv + 1), 0, 1);
  }
  static buildingContributionV31(buildingId, level, sameBranchCount) {
    // 单座建筑文化贡献：perLevel[level] × 集聚(1 + 0.05 × 同系座数，上限 1.5)。
    const def = CULT31_BUILDING_CULTURE[buildingId];
    if (!def) return 0;
    const lv = cult31ClampV31(Math.round(level) || 1, 1, 3);
    const cluster = 1 + Math.min(0.5, 0.05 * Math.max(0, sameBranchCount - 1));
    return cult31Round2V31(def.perLevel[lv - 1] * cluster);
  }
  static buildingsRawV31(buildings) {
    // 输入 [{id, level}]，输出 {perBranch, total, counts}；未知 id 跳过（返回 0，不报错）。
    const perBranch = { art: 0, music: 0, literature: 0, sports: 0, festival: 0 };
    const counts = { art: 0, music: 0, literature: 0, sports: 0, festival: 0 };
    const list = Array.isArray(buildings) ? buildings : [];
    for (const b of list) {
      const def = CULT31_BUILDING_CULTURE[b.id];
      if (!def) continue;
      counts[def.branch] += 1;
    }
    for (const b of list) {
      const def = CULT31_BUILDING_CULTURE[b.id];
      if (!def) continue;
      const lv = b.level !== undefined ? b.level : (b.lv !== undefined ? b.lv : 1);
      perBranch[def.branch] += CultureV31Calculator.buildingContributionV31(b.id, lv, counts[def.branch]);
    }
    let total = 0;
    for (const k in perBranch) { perBranch[k] = cult31Round2V31(perBranch[k]); total += perBranch[k]; }
    return { perBranch: perBranch, total: cult31Round2V31(total), counts: counts };
  }
  static policyRawV31(activePolicyIds) {
    // 输入已激活政策 id 数组，输出 {perBranch, satAdd, immAdd, upkeep, conflictRisk}。
    const perBranch = { art: 0, music: 0, literature: 0, sports: 0, festival: 0 };
    let satAdd = 0; let immAdd = 0; let upkeep = 0; let conflictRisk = 0;
    const ids = Array.isArray(activePolicyIds) ? activePolicyIds : [];
    const byId = {};
    for (const p of CULT31_POLICIES) byId[p.id] = p;
    for (const id of ids) {
      const p = byId[id];
      if (!p) continue;
      perBranch[p.branch] += p.add;
      satAdd += p.satAdd; immAdd += p.immAdd; upkeep += p.upkeep;
      if (p.conflictRisk > conflictRisk) conflictRisk = p.conflictRisk;
    }
    return { perBranch: perBranch, satAdd: cult31Round2V31(satAdd), immAdd: cult31Round2V31(immAdd), upkeep: upkeep, conflictRisk: conflictRisk };
  }
  static policyMulV31(activePolicyIds) {
    // 政策全局倍率连乘：mul 总乘积，上限 1.5，下限 0.8。
    let mul = 1;
    const ids = Array.isArray(activePolicyIds) ? activePolicyIds : [];
    const byId = {};
    for (const p of CULT31_POLICIES) byId[p.id] = p;
    for (const id of ids) { const p = byId[id]; if (p) mul *= p.mul; }
    return cult31Round2V31(cult31ClampV31(mul, 0.8, 1.5));
  }
  static synergyMulV31(levels) {
    // 协同倍率：每条协同 a,b 均 ≥3 时，target 系 × (1 + min(lvA, lvB) × coef)。
    const out = { art: 1, music: 1, literature: 1, sports: 1, festival: 1 };
    for (const s of CULT31_BRANCH_SYNERGY) {
      const la = cult31SafeNumV31(levels[s.a], 0); const lb = cult31SafeNumV31(levels[s.b], 0);
      if (la >= s.minLevel && lb >= s.minLevel) {
        out[s.target] = cult31Round2V31(out[s.target] * (1 + Math.min(la, lb) * s.coef));
      }
    }
    return out;
  }
  static branchValueV31(raw, mul) {
    // 系价值 = diminish(raw) × mul；mul 缺省 1。
    return cult31Round2V31(CultureV31Calculator.diminishV31(raw) * (mul || 1));
  }
  static totalCultureV31(perBranchValue) {
    // 总文化值 = 五系价值之和（已递减、已乘协同与政策倍率）。
    let total = 0;
    for (const k in perBranchValue) total += cult31SafeNumV31(perBranchValue[k], 0);
    return cult31Round2V31(total);
  }
  static satisfactionBonusV31(totalCulture, extraSat) {
    // 满意度加成 = min(25, 0.06 × V) + 政策/节日额外；结果夹取 0..40。
    const base = Math.min(CULT31_SAT_CAP, CULT31_SAT_PER_CULTURE * Math.max(0, totalCulture));
    return cult31Round2V31(cult31ClampV31(base + cult31SafeNumV31(extraSat, 0), 0, 40));
  }
  static immigrationMulV31(totalCulture, extraImm) {
    // 移民吸引力 = 1 + min(0.60, V/500) + 额外；夹取 1..2。
    const base = Math.min(CULT31_IMMIGRATION_CAP, Math.max(0, totalCulture) * CULT31_IMMIGRATION_PER_CULTURE);
    return cult31Round2V31(cult31ClampV31(1 + base + cult31SafeNumV31(extraImm, 0), 1, 2));
  }
  static growthMulV31(avgLevel, immigrationMul) {
    // 人口增长修正 = 1 + 0.02 × 平均等级 + 0.10 × (imm − 1)；夹取 0.5..2。
    const g = 1 + CULT31_GROWTH_PER_AVG_LEVEL * Math.max(0, avgLevel) + 0.10 * (Math.max(1, immigrationMul) - 1);
    return cult31Round2V31(cult31ClampV31(g, 0.5, 2));
  }
  static workScoreV31(workDef, branchLevel, celebTeachMul, rand01) {
    // 作品评分 = baseScore + 系等级 × 3 + 名人教学 × 50 + (rand01 − 0.5) × 10；夹取 0..100。
    const base = cult31SafeNumV31(workDef.baseScore, 50);
    const lvBonus = 3 * Math.max(0, branchLevel || 0);
    const teach = 50 * cult31SafeNumV31(celebTeachMul, 0);
    const jitter = ((rand01 === undefined ? 0.5 : rand01) - 0.5) * 10;
    return cult31Round2V31(cult31ClampV31(base + lvBonus + teach + jitter, 0, 100));
  }
  static workRevenueV31(workDef, score, venueMul, fame) {
    // 作品收益 = basePrice × 品质倍率(score) × (1 + fame/100) × venueMul。
    const q = cult31QualityMulOfV31(score);
    const f = 1 + Math.max(0, cult31SafeNumV31(fame, 0)) / 100;
    return Math.round(cult31SafeNumV31(workDef.basePrice, 0) * q * f * (venueMul || 1));
  }
  static workCreateCostV31(workDef, branchLevel) {
    // 创作花费 = cost × 系成本折扣 costMul（1 − 0.02 × Lv，下限 0.80），向下取整，最少 1。
    const lv = Math.max(0, branchLevel || 0);
    const mul = Math.max(0.80, 1 - 0.02 * lv);
    const out = {};
    for (const k in workDef.cost) out[k] = Math.max(1, Math.floor(workDef.cost[k] * mul));
    return out;
  }
  static festivalNetV31(festDef) {
    // 节日净收益（星币当量）= 天数 × (bonusRaw × 0.9 + bonusSat × 10) − prepCost − upkeep × 天数。
    const d = festDef.durationDays;
    return Math.round(d * (festDef.bonusRaw * 0.9 + festDef.bonusSat * 10) - festDef.prepCost - festDef.upkeepPerDay * d);
  }
  static festivalDailyBonusV31(festDef) {
    // 节日进行中每日加成：主系 raw、其余四系 raw × 0.4、满意度、移民。
    const out = { perBranch: { art: 0, music: 0, literature: 0, sports: 0, festival: 0 }, sat: 0, imm: 0 };
    out.perBranch[festDef.branch] = festDef.bonusRaw;
    for (const k in out.perBranch) if (k !== festDef.branch) out.perBranch[k] = cult31Round2V31(festDef.bonusRaw * 0.4);
    out.sat = festDef.bonusSat; out.imm = festDef.bonusImm;
    return out;
  }
  static celebDailyNetV31(celebDef) {
    // 名人日净收益 = bonusRaw × 0.9 + teachMul × 40 − salary。
    return cult31Round2V31(celebDef.bonusRaw * 0.9 + celebDef.teachMul * 40 - celebDef.salary);
  }
  static celebRecruitCostV31(celebDef) {
    // 招募费 = salary × 10 + fame × 5（与数据表一致，复算校验用）。
    return celebDef.salary * 10 + celebDef.fame * 5;
  }
  static tourNetV31(tourDef, workRevenues, celebWith) {
    // 巡展净收益 = Σ作品收益 × 路线倍率 × (名人随行 1.15) − 运输成本。
    let sum = 0;
    for (const r of workRevenues) sum += cult31SafeNumV31(r, 0);
    const gross = sum * tourDef.mul * (celebWith ? 1.15 : 1);
    return Math.round(gross - tourDef.transportCost);
  }
  static conflictDailyChanceV31(conflictDef, policyRisk) {
    // 冲突日概率 = weight × (1 + 政策风险)；夹取 0..0.5。
    return cult31Round2V31(cult31ClampV31(conflictDef.weight * (1 + cult31SafeNumV31(policyRisk, 0)), 0, 0.5));
  }
  static milestoneRewardV31(milestone) {
    // 里程碑奖励复算：credits = 50 × 序号；xp = 20 × 序号（序号由 threshold/25 得）。
    const n = Math.round(milestone.threshold / 25);
    return { credits: 50 * n, xp: 20 * n, satDays: milestone.satDays };
  }
  static venueFullMulV31(venueDef) {
    // 场馆满展倍率 = exhibitMul × (1 + 0.05 × capacity)，与数据表 fullMul 一致。
    return cult31Round2V31(venueDef.exhibitMul * (1 + 0.05 * venueDef.capacity));
  }
  static avgLevelV31(levels) {
    // 五系平均等级。
    let sum = 0; let n = 0;
    for (const k of CULT31_BRANCH_IDS) { sum += cult31SafeNumV31(levels[k], 0); n += 1; }
    return cult31Round2V31(sum / Math.max(1, n));
  }
  static xpGainPerMinV31(levels, buildingsRawTotal, worksCount, celebsCount) {
    // 每分钟系经验（全系均分基数）：1.0 + 建筑 raw × 0.01 + 作品数 × 0.2 + 名人数 × 0.3。
    const base = 1.0 + buildingsRawTotal * 0.01 + worksCount * 0.2 + celebsCount * 0.3;
    return cult31Round2V31(base);
  }
}

/* ============================== CultureV31BranchState：单系状态 ============================== */
class CultureV31BranchState {
  constructor(branchId) {
    this.branch = branchId;
    this.xp = 0;
    this.level = 0;
    this.totalEarnedXp = 0;
    this.worksCreated = 0;
    this.festivalsHeld = 0;
  }
  addXpV31(amount) {
    // 加经验并升级：返回 {leveledUp, newLevel, gained}；升级不扣经验（累计制）。
    const add = Math.max(0, cult31SafeNumV31(amount, 0));
    const before = this.level;
    this.xp += add; this.totalEarnedXp += add;
    this.level = CultureV31Calculator.levelFromXpV31(this.xp);
    return { leveledUp: this.level > before, newLevel: this.level, gained: add, before: before };
  }
  levelDefV31() {
    // 当前等级定义；0 级返回 null（用 Lv1 定义的 needXp 做进度分母时调用方处理）。
    if (this.level < 1) return null;
    return CULT31_BRANCH_LEVELS[this.branch].levels[this.level];
  }
  nextLevelDefV31() {
    if (this.level >= CULT31_MAX_LEVEL) return null;
    return CULT31_BRANCH_LEVELS[this.branch].levels[this.level + 1];
  }
  progressV31() { return CultureV31Calculator.xpProgressV31(this.xp); }
  xpToNextV31() { return CultureV31Calculator.xpToNextV31(this.xp); }
  outputPerMinV31() {
    // 本系等级产出 culture/min：2.0 × L^1.25；0 级为 0。
    return cult31LevelOutputV31(this.level);
  }
  saveV31() {
    return { branch: this.branch, xp: this.xp, level: this.level, totalEarnedXp: this.totalEarnedXp, worksCreated: this.worksCreated, festivalsHeld: this.festivalsHeld };
  }
  loadV31(data) {
    if (!data) return;
    this.xp = cult31SafeNumV31(data.xp, 0);
    this.level = cult31ClampV31(Math.round(cult31SafeNumV31(data.level, 0)), 0, CULT31_MAX_LEVEL);
    this.totalEarnedXp = cult31SafeNumV31(data.totalEarnedXp, this.xp);
    this.worksCreated = cult31SafeNumV31(data.worksCreated, 0);
    this.festivalsHeld = cult31SafeNumV31(data.festivalsHeld, 0);
    // 存档等级与经验不一致时以经验为准重算（防旧档漂移）。
    const recomputed = CultureV31Calculator.levelFromXpV31(this.xp);
    if (recomputed !== this.level) this.level = recomputed;
  }
}

/* ============================== CultureV31WorkInstance：作品实例 ============================== */
class CultureV31WorkInstance {
  constructor(workDef, score, creatorCelebId) {
    this.defId = workDef.id;
    this.kind = workDef.kind;
    this.branch = workDef.branch;
    this.name = workDef.name;
    this.score = score;
    this.tier = cult31QualityTierOfV31(score);
    this.tierName = CULT31_QUALITY_TIERS[this.tier];
    this.fame = workDef.fame;
    this.creatorCelebId = creatorCelebId || null;
    this.venueId = null;
    this.exhibitedDays = 0;
    this.totalRevenue = 0;
    this.timesExhibited = 0;
    this.createdDay = 0;
    this.onTour = false;
  }
  revenueAtV31(venueMul) {
    // 按当前名气与场馆倍率实算单次展览收益。
    const def = CultureV31WorkInstance.defOfV31(this.defId);
    if (!def) return 0;
    return CultureV31Calculator.workRevenueV31(def, this.score, venueMul || 1, this.fame);
  }
  static defOfV31(defId) {
    for (const w of CULT31_WORKS) if (w.id === defId) return w;
    return null;
  }
  exhibitV31(venueDef) {
    // 展览一次：收益 = workRevenue × 场馆倍率（满展用 fullMul）；名气 +2~6（确定性种子）；返回收益。
    if (!venueDef) return { ok: false, revenue: 0, reason: 'no-venue' };
    const full = venueDef.capacity <= 0 ? venueDef.exhibitMul : venueDef.exhibitMul;
    const rev = this.revenueAtV31(full);
    this.totalRevenue += rev;
    this.timesExhibited += 1;
    this.exhibitedDays += 1;
    this.venueId = venueDef.id;
    const rng = cult31MulberryV31(this.timesExhibited * 131 + this.score * 7);
    this.fame = Math.min(100, this.fame + 2 + Math.floor(rng() * 5));
    return { ok: true, revenue: rev, fame: this.fame, tierName: this.tierName };
  }
  decayFameV31(days) {
    // 名气每日衰减 0.5，下限 0；展览中不衰减（调用方在非展览日调用）。
    this.fame = Math.max(0, cult31Round2V31(this.fame - CULT31_FAME_DECAY_PER_DAY * Math.max(0, days)));
  }
  residentRawV31() {
    // 作品常驻文化 raw：品质档 × 2 + 名气 × 0.05；传世档常驻 12 + 名气加成。
    return cult31Round2V31(this.tier * 2 + this.fame * 0.05);
  }
  saveV31() {
    return { defId: this.defId, kind: this.kind, branch: this.branch, name: this.name, score: this.score, tier: this.tier, tierName: this.tierName, fame: this.fame, creatorCelebId: this.creatorCelebId, venueId: this.venueId, exhibitedDays: this.exhibitedDays, totalRevenue: this.totalRevenue, timesExhibited: this.timesExhibited, createdDay: this.createdDay, onTour: this.onTour };
  }
  loadV31(data) {
    if (!data) return;
    this.defId = data.defId; this.kind = data.kind; this.branch = data.branch; this.name = data.name;
    this.score = cult31SafeNumV31(data.score, 0); this.tier = cult31QualityTierOfV31(this.score);
    this.tierName = CULT31_QUALITY_TIERS[this.tier];
    this.fame = cult31SafeNumV31(data.fame, 0); this.creatorCelebId = data.creatorCelebId || null;
    this.venueId = data.venueId || null; this.exhibitedDays = cult31SafeNumV31(data.exhibitedDays, 0);
    this.totalRevenue = cult31SafeNumV31(data.totalRevenue, 0); this.timesExhibited = cult31SafeNumV31(data.timesExhibited, 0);
    this.createdDay = cult31SafeNumV31(data.createdDay, 0); this.onTour = !!data.onTour;
  }
}

/* ============================== CultureV31CelebrityInstance：名人实例 ============================== */
class CultureV31CelebrityInstance {
  constructor(celebDef) {
    this.defId = celebDef.id;
    this.branch = celebDef.branch;
    this.name = celebDef.name;
    this.title = celebDef.title;
    this.skill = celebDef.skill;
    this.fame = celebDef.fame;
    this.salary = celebDef.salary;
    this.bonusRaw = celebDef.bonusRaw;
    this.teachMul = celebDef.teachMul;
    this.loyalty = celebDef.loyalty;
    this.recruitedDay = 0;
    this.daysServed = 0;
    this.raiseCount = 0;
    this.wantRaise = false;
    this.onTour = false;
  }
  static defOfV31(defId) {
    for (const c of CULT31_CELEBRITIES) if (c.id === defId) return c;
    return null;
  }
  dailyNetV31() {
    // 日净收益 = bonusRaw × 0.9 + teachMul × 40 − salary（与计算器一致）。
    return CultureV31Calculator.celebDailyNetV31({ bonusRaw: this.bonusRaw, teachMul: this.teachMul, salary: this.salary });
  }
  dailyTickV31() {
    // 每日：服务天数 +1；忠诚 +0.07（年 +25，上限 95）；名气 −0.5（下限 5）。
    this.daysServed += 1;
    this.loyalty = Math.min(95, cult31Round2V31(this.loyalty + 0.07));
    this.fame = Math.max(5, cult31Round2V31(this.fame - CULT31_FAME_DECAY_PER_DAY));
  }
  raiseCheckV31(rand01) {
    // 每 30 天检定：loyalty < 50 且 fame > 70 时，rand01 < 0.25 提出加薪（salary +20%）。
    if (this.daysServed % 30 !== 0) return { raise: false };
    if (this.loyalty < 50 && this.fame > 70 && rand01 < 0.25) {
      this.wantRaise = true;
      return { raise: true, newSalary: Math.round(this.salary * 1.2) };
    }
    return { raise: false };
  }
  grantRaiseV31() {
    // 批准加薪：salary +20%，忠诚 +15（上限 95），加薪次数 +1。
    if (!this.wantRaise) return { ok: false };
    this.salary = Math.round(this.salary * 1.2);
    this.loyalty = Math.min(95, this.loyalty + 15);
    this.raiseCount += 1; this.wantRaise = false;
    return { ok: true, salary: this.salary, loyalty: this.loyalty };
  }
  refuseRaiseV31() {
    // 拒绝加薪：忠诚 −12；忠诚 < 30 时离职（调用方据此移除）。
    this.loyalty = Math.max(0, this.loyalty - 12);
    this.wantRaise = false;
    return { ok: true, loyalty: this.loyalty, leaves: this.loyalty < 30 };
  }
  saveV31() {
    return { defId: this.defId, branch: this.branch, name: this.name, title: this.title, skill: this.skill, fame: this.fame, salary: this.salary, bonusRaw: this.bonusRaw, teachMul: this.teachMul, loyalty: this.loyalty, recruitedDay: this.recruitedDay, daysServed: this.daysServed, raiseCount: this.raiseCount, wantRaise: this.wantRaise, onTour: this.onTour };
  }
  loadV31(data) {
    if (!data) return;
    this.defId = data.defId; this.branch = data.branch; this.name = data.name; this.title = data.title;
    this.skill = cult31SafeNumV31(data.skill, 50); this.fame = cult31SafeNumV31(data.fame, 0);
    this.salary = cult31SafeNumV31(data.salary, 0); this.bonusRaw = cult31SafeNumV31(data.bonusRaw, 0);
    this.teachMul = cult31SafeNumV31(data.teachMul, 0); this.loyalty = cult31SafeNumV31(data.loyalty, 50);
    this.recruitedDay = cult31SafeNumV31(data.recruitedDay, 0); this.daysServed = cult31SafeNumV31(data.daysServed, 0);
    this.raiseCount = cult31SafeNumV31(data.raiseCount, 0); this.wantRaise = !!data.wantRaise; this.onTour = !!data.onTour;
  }
}

/* ============================== CultureV31FestivalPlan：节日筹办 ============================== */
class CultureV31FestivalPlan {
  constructor(festDef, startDay) {
    this.defId = festDef.id;
    this.name = festDef.name;
    this.branch = festDef.branch;
    this.scale = festDef.scale;
    this.month = festDef.month;
    this.startDay = startDay;
    this.endDay = startDay + festDef.durationDays;
    this.prepDaysLeft = CULT31_FESTIVAL_PREP_DAYS;
    this.state = 'preparing'; // preparing → active → done / cancelled
    this.dailyBonus = CultureV31Calculator.festivalDailyBonusV31(festDef);
    this.netValue = CultureV31Calculator.festivalNetV31(festDef);
  }
  static defOfV31(defId) {
    for (const f of CULT31_FESTIVALS) if (f.id === defId) return f;
    return null;
  }
  tickDayV31(day) {
    // 每日推进：筹办期倒数；到 startDay 转 active；过 endDay 转 done；返回状态变迁。
    if (this.state === 'preparing') {
      this.prepDaysLeft -= 1;
      if (day >= this.startDay) { this.state = 'active'; return { changed: true, state: 'active' }; }
      return { changed: false, state: 'preparing' };
    }
    if (this.state === 'active' && day >= this.endDay) {
      this.state = 'done'; return { changed: true, state: 'done' };
    }
    return { changed: false, state: this.state };
  }
  isActiveV31() { return this.state === 'active'; }
  cancelV31() {
    // 取消：筹办期退 50% 筹办费；进行中不退。调用方按 state 结算退款。
    const refundRate = this.state === 'preparing' ? 0.5 : 0;
    this.state = 'cancelled';
    return { ok: true, refundRate: refundRate };
  }
  saveV31() {
    return { defId: this.defId, name: this.name, branch: this.branch, scale: this.scale, month: this.month, startDay: this.startDay, endDay: this.endDay, prepDaysLeft: this.prepDaysLeft, state: this.state, netValue: this.netValue };
  }
  loadV31(data) {
    if (!data) return;
    this.defId = data.defId; this.name = data.name; this.branch = data.branch; this.scale = data.scale;
    this.month = cult31SafeNumV31(data.month, 1); this.startDay = cult31SafeNumV31(data.startDay, 0);
    this.endDay = cult31SafeNumV31(data.endDay, 0); this.prepDaysLeft = cult31SafeNumV31(data.prepDaysLeft, 0);
    this.state = data.state || 'preparing'; this.netValue = cult31SafeNumV31(data.netValue, 0);
    const def = CultureV31FestivalPlan.defOfV31(this.defId);
    this.dailyBonus = def ? CultureV31Calculator.festivalDailyBonusV31(def) : { perBranch: { art: 0, music: 0, literature: 0, sports: 0, festival: 0 }, sat: 0, imm: 0 };
  }
}

/* ============================== CultureV31ConflictInstance：冲突事件实例 ============================== */
class CultureV31ConflictInstance {
  constructor(conflictDef, day) {
    this.defId = conflictDef.id;
    this.branch = conflictDef.branch;
    this.name = conflictDef.name;
    this.day = day;
    this.resolved = false;
    this.choiceIndex = -1;
    this.expiresDay = day + 3; // 3 天内不抉择则自动按折中处理（满意度 −1）。
  }
  static defOfV31(defId) {
    for (const c of CULT31_CONFLICTS) if (c.id === defId) return c;
    for (const c of CULT31_CONFLICTS_X) if (c.id === defId) return c;
    return null;
  }
  resolveV31(choiceIndex) {
    // 抉择：返回效果 {sat, culture, credits, imm, xp, branch}；越界返回 {ok:false}。
    const def = CultureV31ConflictInstance.defOfV31(this.defId);
    if (!def || this.resolved) return { ok: false, reason: this.resolved ? 'already-resolved' : 'no-def' };
    if (choiceIndex < 0 || choiceIndex >= def.choices.length) return { ok: false, reason: 'bad-choice' };
    const ch = def.choices[choiceIndex];
    this.resolved = true; this.choiceIndex = choiceIndex;
    return { ok: true, sat: ch.sat, culture: ch.culture, credits: ch.credits, imm: ch.imm, xp: ch.xp, branch: def.branch, label: ch.label };
  }
  autoResolveV31() {
    // 过期自动折中：满意度 −1，无其他效果。
    if (this.resolved) return { ok: false };
    this.resolved = true; this.choiceIndex = 1;
    return { ok: true, auto: true, sat: -1, culture: 0, credits: 0, imm: 0, xp: 0, branch: this.branch, label: '逾期自动折中' };
  }
  saveV31() {
    return { defId: this.defId, branch: this.branch, name: this.name, day: this.day, resolved: this.resolved, choiceIndex: this.choiceIndex, expiresDay: this.expiresDay };
  }
  loadV31(data) {
    if (!data) return;
    this.defId = data.defId; this.branch = data.branch; this.name = data.name; this.day = cult31SafeNumV31(data.day, 0);
    this.resolved = !!data.resolved; this.choiceIndex = cult31SafeNumV31(data.choiceIndex, -1);
    this.expiresDay = cult31SafeNumV31(data.expiresDay, this.day + 3);
  }
}


/* ============================== CultureV31Manager：文化系统管理器 ============================== */
/* 状态：五系经验/等级、作品实例、名人实例、节日计划、冲突实例、政策激活、资金、里程碑、日志。 */
/* 时间单位：游戏日 day（1 天 = 60000 ms 游戏时间，与 tick(dtMs) 累积换算）； */
/* tick 每 1000 ms 累积一次文化产出与经验；每日结算（节日/名人薪资/名气/冲突检定）在 day 推进时执行。 */
class CultureV31Manager {
  constructor() {
    this.version = CULT31_VERSION;
    this.branches = {};
    for (const b of CULT31_BRANCH_IDS) this.branches[b] = new CultureV31BranchState(b);
    this.works = [];          // CultureV31WorkInstance[]
    this.celebs = [];         // CultureV31CelebrityInstance[]
    this.festivals = [];      // CultureV31FestivalPlan[]
    this.conflicts = [];      // CultureV31ConflictInstance[]
    this.exhibitions = [];   // {defId, endDay} 进行中的主题展览
    this.activePolicies = []; // policy id[]
    this.funds = 200;         // 文化专项资金（星币），与 game.economy 互通时由 tick 结算
    this.totalFundsEarned = 0;
    this.totalFundsSpent = 0;
    this.day = 0;
    this._accumMs = 0;
    this._lastDay = 0;
    this._rng = cult31MulberryV31(310731);
    this.claimedMilestones = [];
    this.log = [];            // 最近 100 条事件日志 {day, text}
    this._conflictCooldown = {}; // defId → day（30 天内不重复）
    this._festivalsThisYear = 0;
    this._largeFestivalsThisYear = 0;
    this._year = 0;
    this.cached = { totalCulture: 0, perBranch: { art: 0, music: 0, literature: 0, sports: 0, festival: 0 }, satBonus: 0, immMul: 1, growthMul: 1 };
    this._recomputeV31();
  }

  /* ---------- 日志 ---------- */
  logV31(text) {
    this.log.push({ day: this.day, text: String(text) });
    if (this.log.length > 100) this.log.splice(0, this.log.length - 100);
  }

  /* ---------- game 快照读取（全部防御性） ---------- */
  readGameV31(game) {
    // 从 game 安全读取：人口、建筑列表、背包、政策、科技倍率、幸福度；缺失一律默认值。
    const g = game || {};
    const popCount = g.pop ? cult31SafeNumV31(g.pop.count, 0) : 0;
    let buildings = [];
    if (g.builder && Array.isArray(g.builder.buildings)) buildings = g.builder.buildings;
    else if (Array.isArray(g.buildings)) buildings = g.buildings;
    const inv = (g.player && g.player.inv) ? g.player.inv : {};
    let policyIds = [];
    if (g.policy && Array.isArray(g.policy.active)) policyIds = g.policy.active.slice();
    else if (Array.isArray(g.activePolicies)) policyIds = g.activePolicies.slice();
    let techMul = 1;
    if (g.tech && typeof g.tech.mul === 'function') {
      try { techMul = cult31SafeNumV31(g.tech.mul('cultureMul'), 1) || 1; } catch (e) { techMul = 1; }
    }
    let happiness = null;
    if (g.economy && isFinite(Number(g.economy.happiness))) happiness = Number(g.economy.happiness);
    return { popCount: popCount, buildings: buildings, inv: inv, policyIds: policyIds, techMul: techMul, happiness: happiness };
  }

  /* ---------- 文化值计算 ---------- */
  computeCultureV31(game) {
    // 全量实算：建筑 raw + 政策 raw + 作品常驻 + 名人常驻 + 节日进行中加成 → 协同/政策倍率 → 递减 → 系价值 → 总值。
    const snap = this.readGameV31(game);
    const bRaw = CultureV31Calculator.buildingsRawV31(snap.buildings);
    const pRaw = CultureV31Calculator.policyRawV31(this.activePolicies.concat(snap.policyIds.filter(function (id) {
      for (const p of CULT31_POLICIES) if (p.id === id) return true;
      return false;
    })));
    const levels = this.levelsV31();
    const synMul = CultureV31Calculator.synergyMulV31(levels);
    const polMul = CultureV31Calculator.policyMulV31(this.activePolicies);
    const raw = { art: 0, music: 0, literature: 0, sports: 0, festival: 0 };
    for (const k of CULT31_BRANCH_IDS) {
      raw[k] += bRaw.perBranch[k] + pRaw.perBranch[k];
      raw[k] += this.branches[k].outputPerMinV31();
    }
    for (const w of this.works) raw[w.branch] += w.residentRawV31();
    for (const c of this.celebs) raw[c.branch] += c.bonusRaw;
    let festSat = 0; let festImm = 0;
    for (const f of this.festivals) {
      if (!f.isActiveV31()) continue;
      for (const k of CULT31_BRANCH_IDS) raw[k] += f.dailyBonus.perBranch[k];
      festSat += f.dailyBonus.sat; festImm += f.dailyBonus.imm;
    }
    const perBranch = {};
    for (const k of CULT31_BRANCH_IDS) {
      perBranch[k] = CultureV31Calculator.branchValueV31(raw[k] * synMul[k], polMul);
    }
    const total = CultureV31Calculator.totalCultureV31(perBranch);
    const satBonus = CultureV31Calculator.satisfactionBonusV31(total, pRaw.satAdd + festSat);
    const immMul = CultureV31Calculator.immigrationMulV31(total, pRaw.immAdd + festImm);
    const avgLv = CultureV31Calculator.avgLevelV31(levels);
    const growthMul = CultureV31Calculator.growthMulV31(avgLv, immMul);
    return { raw: raw, perBranch: perBranch, total: total, satBonus: satBonus, immMul: immMul, growthMul: growthMul, avgLevel: avgLv, buildingsRaw: bRaw, policyRaw: pRaw, synergyMul: synMul, policyMul: polMul };
  }
  _recomputeV31(game) {
    const r = this.computeCultureV31(game || null);
    this.cached = { totalCulture: r.total, perBranch: r.perBranch, satBonus: r.satBonus, immMul: r.immMul, growthMul: r.growthMul };
    return r;
  }
  levelsV31() {
    const out = {};
    for (const k of CULT31_BRANCH_IDS) out[k] = this.branches[k].level;
    return out;
  }
  getModifiersV31(game) {
    // 供 game / economy 读取的修正包：幸福度加成、移民倍率、人口增长倍率、文化值、五系值。
    const r = game ? this.computeCultureV31(game) : this._recomputeV31(null);
    return { happinessAdd: r.satBonus, immigrationMul: r.immMul, growthMul: r.growthMul, cultureValue: r.total, perBranch: r.perBranch, avgLevel: r.avgLevel, version: CULT31_VERSION };
  }
  cultureValueV31(game) { return this.getModifiersV31(game).cultureValue; }

  /* ---------- 作品：创作 / 展览 / 巡展 ---------- */
  workSlotsV31() {
    // 作品槽位 = 基础 4 + 五系等级之和每满 10 级 +1（上限 12）。
    let sumLv = 0;
    for (const k of CULT31_BRANCH_IDS) sumLv += this.branches[k].level;
    return Math.min(12, CULT31_WORK_SLOTS_BASE + Math.floor(sumLv / 10));
  }
  canCreateWorkV31(workDefId) {
    const def = CultureV31WorkInstance.defOfV31(workDefId);
    if (!def) return { ok: false, reason: 'no-def' };
    if (this.works.length >= this.workSlotsV31()) return { ok: false, reason: 'slots-full', slots: this.workSlotsV31() };
    return { ok: true, def: def, cost: CultureV31Calculator.workCreateCostV31(def, this.branches[def.branch].level) };
  }
  createWorkV31(game, workDefId, celebDefId) {
    // 创作：扣背包资源（铁/钢/科技），评分 = base + 系等级 × 3 + 名人教学 + 随机 ±5；名人需已招募。
    const chk = this.canCreateWorkV31(workDefId);
    if (!chk.ok) return chk;
    const def = chk.def;
    const snap = this.readGameV31(game);
    const inv = snap.inv;
    let celeb = null;
    if (celebDefId) {
      for (const c of this.celebs) if (c.defId === celebDefId) celeb = c;
      if (!celeb) return { ok: false, reason: 'no-celeb' };
    }
    for (const k in chk.cost) {
      if (cult31SafeNumV31(inv[k], 0) < chk.cost[k]) return { ok: false, reason: 'not-enough-' + k, need: chk.cost[k], have: cult31SafeNumV31(inv[k], 0) };
    }
    for (const k in chk.cost) inv[k] -= chk.cost[k];
    const teach = celeb ? celeb.teachMul : 0;
    const score = CultureV31Calculator.workScoreV31(def, this.branches[def.branch].level, teach, this._rng());
    const inst = new CultureV31WorkInstance(def, score, celeb ? celeb.defId : null);
    inst.createdDay = this.day;
    this.works.push(inst);
    this.branches[def.branch].worksCreated += 1;
    this.branches[def.branch].addXpV31(15 + inst.tier * 5);
    this.logV31('创作「' + def.name + '」评分 ' + score + '（' + inst.tierName + '）');
    this._recomputeV31(game);
    return { ok: true, work: inst, score: score, tierName: inst.tierName, cost: chk.cost };
  }
  venueDefV31(venueId) {
    for (const v of CULT31_VENUES) if (v.id === venueId) return v;
    return null;
  }
  exhibitWorkV31(game, workIndex, venueId) {
    // 展览：场馆需解锁（系等级 ≥ unlockLevel）；收益进 funds 与 economy（若可写）。
    const inst = this.works[workIndex];
    if (!inst) return { ok: false, reason: 'no-work' };
    const venue = this.venueDefV31(venueId);
    if (!venue) return { ok: false, reason: 'no-venue' };
    if (this.branches[venue.branch].level < venue.unlockLevel) return { ok: false, reason: 'venue-locked', needLevel: venue.unlockLevel };
    const inVenue = this.works.filter(function (w) { return w.venueId === venueId; }).length;
    const mul = inVenue + 1 >= venue.capacity ? CultureV31Calculator.venueFullMulV31(venue) : venue.exhibitMul;
    const exhMul = this._exhibitionMulForV31(inst.kind);
    const r = inst.exhibitV31({ id: venue.id, exhibitMul: mul * exhMul, capacity: venue.capacity });
    if (!r.ok) return r;
    this.funds += r.revenue; this.totalFundsEarned += r.revenue;
    this.depositToGameV31(game, r.revenue);
    this.branches[inst.branch].addXpV31(5);
    this.logV31('展览「' + inst.name + '」于' + venue.name + '，收益 +' + r.revenue + ' 星币');
    this._recomputeV31(game);
    return { ok: true, revenue: r.revenue, fame: r.fame, tierName: r.tierName, venue: venue.name };
  }
  startTourV31(game, tourId, workIndexes, celebDefId) {
    // 巡展：作品需未在巡展中；名人随行需已招募且未在巡展；收益按 tourNet 实算，失败（净负）仍可出行但扣款。
    let tour = null;
    for (const t of CULT31_TOURS) if (t.id === tourId) tour = t;
    if (!tour) return { ok: false, reason: 'no-tour' };
    const works = [];
    for (const idx of workIndexes) {
      const w = this.works[idx];
      if (!w) return { ok: false, reason: 'no-work-' + idx };
      if (w.onTour) return { ok: false, reason: 'already-tour' };
      works.push(w);
    }
    if (works.length === 0) return { ok: false, reason: 'empty-tour' };
    let celeb = null;
    if (celebDefId) {
      for (const c of this.celebs) if (c.defId === celebDefId) celeb = c;
      if (!celeb) return { ok: false, reason: 'no-celeb' };
      if (celeb.onTour) return { ok: false, reason: 'celeb-tour' };
    }
    const revs = works.map(function (w) { return w.revenueAtV31(1); });
    const net = CultureV31Calculator.tourNetV31(tour, revs, !!celeb);
    for (const w of works) { w.onTour = true; w.venueId = null; }
    if (celeb) { celeb.onTour = true; celeb.loyalty = Math.min(95, celeb.loyalty + 2); }
    this.funds += net; this.totalFundsEarned += Math.max(0, net); this.totalFundsSpent += Math.max(0, -net);
    this.depositToGameV31(game, net);
    this.branches[tour.branch].addXpV31(10 * works.length);
    this.logV31('巡展「' + tour.name + '」' + works.length + ' 件作品，净收益 ' + (net >= 0 ? '+' : '') + net + ' 星币');
    for (const w of works) w.onTour = false;
    if (celeb) celeb.onTour = false;
    this._recomputeV31(game);
    return { ok: true, net: net, tour: tour.name, works: works.length };
  }

  /* ---------- 主题展览：策划 / 倍率 ---------- */
  _exhibitionMulForV31(kind) {
    // 进行中的主题展览覆盖该类别作品时，展览收益 × 展览倍率；多个展览取最大值，不叠加。
    let mul = 1;
    for (const e of this.exhibitions) {
      if (this.day > e.endDay) continue;
      for (const x of CULT31_EXHIBITIONS) {
        if (x.id === e.defId && x.kinds.indexOf(kind) !== -1 && x.mul > mul) mul = x.mul;
      }
    }
    return mul;
  }
  planExhibitionV31(game, exhId, workIndexes) {
    // 策划主题展览：主系等级 ≥ minLevel；作品类别须覆盖 kinds（每类至少 1 件）；扣策划费；持续 5 天。
    let def = null;
    for (const x of CULT31_EXHIBITIONS) if (x.id === exhId) def = x;
    if (!def) return { ok: false, reason: 'no-exh' };
    if (this.branches[def.branch].level < def.minLevel) return { ok: false, reason: 'level-low', needLevel: def.minLevel };
    const kindsSeen = {};
    for (const idx of workIndexes) {
      const w = this.works[idx];
      if (!w) return { ok: false, reason: 'no-work-' + idx };
      kindsSeen[w.kind] = true;
    }
    for (const k of def.kinds) if (!kindsSeen[k]) return { ok: false, reason: 'missing-kind-' + k };
    if (this.funds < def.fee) {
      const paid = this.payFromGameV31(game, def.fee - this.funds);
      if (!paid) return { ok: false, reason: 'not-enough-funds', need: def.fee, have: this.funds };
    }
    this.funds -= def.fee; this.totalFundsSpent += def.fee;
    this.exhibitions.push({ defId: def.id, endDay: this.day + def.durationDays });
    this.branches[def.branch].addXpV31(def.xp);
    this._applySatDeltaV31(game, def.sat);
    for (const idx of workIndexes) { const w = this.works[idx]; if (w) w.fame = Math.min(100, w.fame + 3); }
    this.logV31('策划主题展览「' + def.name + '」，持续 ' + def.durationDays + ' 天，' + def.branch + '系经验 +' + def.xp);
    this._recomputeV31(game);
    return { ok: true, name: def.name, mul: def.mul, endDay: this.day + def.durationDays };
  }

  /* ---------- 名人专场 / 联动 / 观众 ---------- */
  holdCelebEventV31(game, celebEventId) {
    // 举办名人专场：名人须已招募；7 天内限 1 场；门票 10% 进文化资金；名气 +5、忠诚 +3。
    let def = null;
    for (const e of CULT31_CELEB_EVENTS) if (e.id === celebEventId) def = e;
    if (!def) return { ok: false, reason: 'no-event' };
    let celeb = null;
    for (const c of this.celebs) if (c.defId === def.celebId) celeb = c;
    if (!celeb) return { ok: false, reason: 'no-celeb' };
    const last = this._lastCelebEventDay || {};
    if (last[def.celebId] !== undefined && this.day - last[def.celebId] < 7) {
      return { ok: false, reason: 'cooldown', nextDay: last[def.celebId] + 7 };
    }
    this._lastCelebEventDay = last;
    last[def.celebId] = this.day;
    const cut = Math.round(def.ticketRevenue * 0.1);
    this.funds += cut; this.totalFundsEarned += cut;
    this.depositToGameV31(game, cut);
    celeb.fame = Math.min(100, celeb.fame + 5);
    celeb.loyalty = Math.min(95, celeb.loyalty + 3);
    this.branches[celeb.branch].addXpV31(15);
    this.logV31('举办' + celeb.name + '专场，门票 ' + def.ticketRevenue + ' 星币，文化资金 +' + cut);
    this._recomputeV31(game);
    return { ok: true, ticket: def.ticketRevenue, cut: cut, fame: celeb.fame, loyalty: celeb.loyalty };
  }
  comboBonusForV31(workDefIdA, workDefIdB) {
    // 查两件作品的联动倍率：无联动返回 1；联动只在两件同时展出时生效（调用方校验展出状态）。
    for (const c of CULT31_WORK_COMBOS) {
      if ((c.works[0] === workDefIdA && c.works[1] === workDefIdB) ||
          (c.works[0] === workDefIdB && c.works[1] === workDefIdA)) return c.mul;
    }
    return 1;
  }
  audienceMulV31(branch) {
    // 观众倍率：按各群体偏好加权，偏好系 1.2、非偏好 0.9，再乘消费倍率均值；返回 {mul, satWeight}。
    let mul = 0; let sat = 0;
    for (const a of CULT31_AUDIENCE_SEGMENTS) {
      const pref = a.branch === branch ? 1.2 : 0.9;
      mul += a.share * pref * a.spendMul;
      sat += a.share * a.satWeight;
    }
    return { mul: cult31Round2V31(mul), satWeight: cult31Round2V31(sat) };
  }
  comboExhibitedBonusV31() {
    // 当前同时展出的作品对中触发的联动列表（用于面板展示与收益结算复核）。
    const onShow = this.works.filter(function (w) { return !!w.venueId; });
    const out = [];
    for (let i = 0; i < onShow.length; i++) {
      for (let j = i + 1; j < onShow.length; j++) {
        const m = this.comboBonusForV31(onShow[i].defId, onShow[j].defId);
        if (m > 1) out.push({ a: onShow[i].defId, b: onShow[j].defId, mul: m });
      }
    }
    return out;
  }

  /* ---------- 节日：筹办 / 取消 ---------- */
  planFestivalV31(game, festId, startDay) {
    // 筹办：同月仅 1 个；L 级每年限 2 次；扣筹办费（funds 不足时从 game economy 扣，不足则失败）。
    let def = null;
    for (const f of CULT31_FESTIVALS) if (f.id === festId) def = f;
    if (!def) return { ok: false, reason: 'no-fest' };
    const start = (startDay === undefined ? this.day + CULT31_FESTIVAL_PREP_DAYS : startDay);
    if (start < this.day + CULT31_FESTIVAL_PREP_DAYS) return { ok: false, reason: 'too-soon', earliest: this.day + CULT31_FESTIVAL_PREP_DAYS };
    for (const p of this.festivals) {
      if (p.state === 'cancelled' || p.state === 'done') continue;
      if (p.month === def.month) return { ok: false, reason: 'month-busy', month: def.month };
    }
    if (def.scale === 'L' && this._largeFestivalsThisYear >= 2) return { ok: false, reason: 'large-limit' };
    if (this.funds < def.prepCost) {
      const paid = this.payFromGameV31(game, def.prepCost - this.funds);
      if (!paid) return { ok: false, reason: 'not-enough-funds', need: def.prepCost, have: this.funds };
    }
    this.funds -= def.prepCost; this.totalFundsSpent += def.prepCost;
    const plan = new CultureV31FestivalPlan(def, start);
    this.festivals.push(plan);
    if (def.scale === 'L') this._largeFestivalsThisYear += 1;
    this.logV31('筹办节日「' + def.name + '」，第 ' + start + ' 天开幕，花费 ' + def.prepCost + ' 星币');
    return { ok: true, plan: plan, netValue: plan.netValue };
  }
  cancelFestivalV31(game, festIndex) {
    const plan = this.festivals[festIndex];
    if (!plan) return { ok: false, reason: 'no-plan' };
    const r = plan.cancelV31();
    const def = CultureV31FestivalPlan.defOfV31(plan.defId);
    const refund = Math.round((def ? def.prepCost : 0) * r.refundRate);
    this.funds += refund;
    this.logV31('取消节日「' + plan.name + '」，退款 ' + refund + ' 星币');
    return { ok: true, refund: refund };
  }

  /* ---------- 名人：招募 / 加薪 / 解雇 ---------- */
  recruitCelebrityV31(game, celebId) {
    // 招募：先查是否已招募；招募费 = salary × 10 + fame × 5；从 funds 扣，不足则失败。
    let def = null;
    for (const c of CULT31_CELEBRITIES) if (c.id === celebId) def = c;
    if (!def) return { ok: false, reason: 'no-celeb' };
    for (const c of this.celebs) if (c.defId === celebId) return { ok: false, reason: 'already' };
    const cost = CultureV31Calculator.celebRecruitCostV31(def);
    if (this.funds < cost) {
      const paid = this.payFromGameV31(game, cost - this.funds);
      if (!paid) return { ok: false, reason: 'not-enough-funds', need: cost, have: this.funds };
    }
    this.funds -= cost; this.totalFundsSpent += cost;
    const inst = new CultureV31CelebrityInstance(def);
    inst.recruitedDay = this.day;
    this.celebs.push(inst);
    this.branches[def.branch].addXpV31(10);
    this.logV31('招募' + def.title + '「' + def.name + '」，招募费 ' + cost + ' 星币');
    this._recomputeV31(game);
    return { ok: true, celeb: inst, cost: cost };
  }
  handleRaiseV31(game, celebIndex, approve) {
    const c = this.celebs[celebIndex];
    if (!c) return { ok: false, reason: 'no-celeb' };
    if (!c.wantRaise) return { ok: false, reason: 'no-raise-pending' };
    if (approve) {
      const r = c.grantRaiseV31();
      this.logV31('批准' + c.name + '加薪至 ' + r.salary + '/天，忠诚 ' + r.loyalty);
      return { ok: true, approved: true, salary: r.salary, loyalty: r.loyalty };
    }
    const r = c.refuseRaiseV31();
    if (r.leaves) {
      this.celebs.splice(celebIndex, 1);
      this.logV31(c.name + '因拒绝加薪离职');
      this._recomputeV31(game);
      return { ok: true, approved: false, leaves: true, loyalty: r.loyalty };
    }
    this.logV31('拒绝' + c.name + '加薪，忠诚降至 ' + r.loyalty);
    return { ok: true, approved: false, leaves: false, loyalty: r.loyalty };
  }
  dismissCelebrityV31(game, celebIndex) {
    const c = this.celebs[celebIndex];
    if (!c) return { ok: false, reason: 'no-celeb' };
    this.celebs.splice(celebIndex, 1);
    this.logV31('解雇' + c.name + '（' + c.title + '）');
    this._recomputeV31(game);
    return { ok: true, name: c.name };
  }

  /* ---------- 政策：激活 / 停用 ---------- */
  setPolicyV31(game, policyId, active) {
    let def = null;
    for (const p of CULT31_POLICIES) if (p.id === policyId) def = p;
    if (!def) return { ok: false, reason: 'no-policy' };
    const idx = this.activePolicies.indexOf(policyId);
    if (active && idx === -1) {
      if (this.funds < def.cost) {
        const paid = this.payFromGameV31(game, def.cost - this.funds);
        if (!paid) return { ok: false, reason: 'not-enough-funds', need: def.cost, have: this.funds };
      }
      this.funds -= def.cost; this.totalFundsSpent += def.cost;
      this.activePolicies.push(policyId);
      this.logV31('实施政策「' + def.name + '」，花费 ' + def.cost + ' 星币');
    } else if (!active && idx !== -1) {
      this.activePolicies.splice(idx, 1);
      this.logV31('停用政策「' + def.name + '」');
    }
    this._recomputeV31(game);
    return { ok: true, active: active, upkeep: CultureV31Calculator.policyRawV31(this.activePolicies).upkeep };
  }

  /* ---------- 冲突：检定 / 抉择 ---------- */
  rollConflictV31(game) {
    // 每日检定：遍历未冷却事件，概率 = weight × (1 + 政策风险)；命中则生成实例（同日最多 1 起）。
    const pRaw = CultureV31Calculator.policyRawV31(this.activePolicies);
    const levels = this.levelsV31();
    const all = CULT31_CONFLICTS.concat(CULT31_CONFLICTS_X);
    for (const def of all) {
      if (this._conflictCooldown[def.id] !== undefined && this.day - this._conflictCooldown[def.id] < def.cooldownDays) continue;
      if (levels[def.branch] < def.minLevel) continue;
      if (def.branch2 && levels[def.branch2] < def.minLevel) continue;
      const chance = CultureV31Calculator.conflictDailyChanceV31(def, pRaw.conflictRisk);
      if (this._rng() < chance) {
        const inst = new CultureV31ConflictInstance(def, this.day);
        this.conflicts.push(inst);
        this._conflictCooldown[def.id] = this.day;
        this.logV31('文化冲突：「' + def.name + '」爆发，需在 3 天内抉择');
        return { ok: true, conflict: inst };
      }
    }
    return { ok: false };
  }
  resolveConflictV31(game, conflictIndex, choiceIndex) {
    const inst = this.conflicts[conflictIndex];
    if (!inst) return { ok: false, reason: 'no-conflict' };
    const r = inst.resolveV31(choiceIndex);
    if (!r.ok) return r;
    this.funds += r.credits; this.totalFundsEarned += Math.max(0, r.credits);
    this.branches[r.branch].addXpV31(r.xp);
    if (r.culture) this.branches[r.branch].addXpV31(r.culture);
    this._applySatDeltaV31(game, r.sat);
    this.logV31('冲突「' + inst.name + '」抉择「' + r.label + '」：满意度 ' + (r.sat >= 0 ? '+' : '') + r.sat + '，星币 ' + (r.credits >= 0 ? '+' : '') + r.credits);
    this._recomputeV31(game);
    return r;
  }
  _applySatDeltaV31(game, delta) {
    // 满意度增量：优先写 game.economy.happiness（夹取 0..100），否则记入临时加成待 tick 结算。
    if (!delta) return;
    if (game && game.economy && isFinite(Number(game.economy.happiness))) {
      game.economy.happiness = cult31ClampV31(Number(game.economy.happiness) + delta, 0, 100);
      return;
    }
    this._pendingSat = cult31SafeNumV31(this._pendingSat, 0) + delta;
  }

  /* ---------- 资金与 game.economy 互通 ---------- */
  depositToGameV31(game, amount) {
    // 收入进账：优先 game.economy.balance / credits（存在且为数字时才写），否则只留 funds。
    if (!game || !game.economy || amount === 0) return false;
    if (isFinite(Number(game.economy.balance))) { game.economy.balance += amount; return true; }
    if (isFinite(Number(game.economy.credits))) { game.economy.credits += amount; return true; }
    return false;
  }
  payFromGameV31(game, amount) {
    // 从 game.economy 扣款：余额不足返回 false（调用方据此拒绝操作，不透支）。
    if (!game || !game.economy || amount <= 0) return false;
    if (isFinite(Number(game.economy.balance)) && game.economy.balance >= amount) { game.economy.balance -= amount; return true; }
    if (isFinite(Number(game.economy.credits)) && game.economy.credits >= amount) { game.economy.credits -= amount; return true; }
    return false;
  }

  /* ---------- 里程碑 ---------- */
  checkMilestonesV31(game) {
    // 检查总文化值里程碑：达标且未领取则发奖励（星币进 funds + 最低系经验 + 临时满意度记录）。
    const total = this.cached.totalCulture;
    const claimed = [];
    for (const m of CULT31_MILESTONES) {
      if (total < m.threshold) break;
      if (this.claimedMilestones.indexOf(m.id) !== -1) continue;
      this.claimedMilestones.push(m.id);
      const rw = CultureV31Calculator.milestoneRewardV31(m);
      this.funds += rw.credits; this.totalFundsEarned += rw.credits;
      let lowest = CULT31_BRANCH_IDS[0];
      for (const k of CULT31_BRANCH_IDS) if (this.branches[k].level < this.branches[lowest].level) lowest = k;
      this.branches[lowest].addXpV31(rw.xp);
      this._pendingSat = cult31SafeNumV31(this._pendingSat, 0) + 2;
      this._pendingSatDays = rw.satDays;
      this.logV31('里程碑达成：文化值 ≥ ' + m.threshold + '，奖励 +' + rw.credits + ' 星币');
      claimed.push(m.id);
    }
    return claimed;
  }

  /* ---------- 主循环 ---------- */
  tickV31(game, now, dtMs) {
    // dtMs 为游戏时间毫秒；每 1000 ms 累积 1 次产出；每 60000 ms 推进 1 天并执行每日结算。
    const dt = Math.max(0, cult31SafeNumV31(dtMs, 0));
    this._accumMs += dt;
    let minutes = 0;
    while (this._accumMs >= CULT31_TICK_MS) {
      this._accumMs -= CULT31_TICK_MS;
      minutes += 1;
      this._minuteTickV31(game);
    }
    const days = Math.floor((this._accumMs + dt) / 60000);
    void days;
    // 天推进用累计器：每满 60000 ms 调用 _dayTickV31 一次（用独立累计避免与分钟累计混淆）。
    this._dayAccumMs = cult31SafeNumV31(this._dayAccumMs, 0) + dt;
    while (this._dayAccumMs >= 60000) {
      this._dayAccumMs -= 60000;
      this.day += 1;
      this._dayTickV31(game);
    }
    return { minutes: minutes, day: this.day, totalCulture: this.cached.totalCulture };
  }
  _minuteTickV31(game) {
    // 每分钟：五系经验 += xpGain（全系同值，按系等级加权：高等级系得 60%，其余均分 40%）。
    const snap = this.readGameV31(game);
    const bRaw = CultureV31Calculator.buildingsRawV31(snap.buildings);
    const gain = CultureV31Calculator.xpGainPerMinV31(this.levelsV31(), bRaw.total, this.works.length, this.celebs.length);
    const levels = this.levelsV31();
    let sumLv = 0;
    for (const k of CULT31_BRANCH_IDS) sumLv += levels[k];
    for (const k of CULT31_BRANCH_IDS) {
      const weight = sumLv > 0 ? (0.4 / 5 + 0.6 * levels[k] / sumLv) : 0.2;
      const before = this.branches[k].level;
      const r = this.branches[k].addXpV31(gain * weight * (snap.techMul || 1));
      if (r.leveledUp) this.logV31(CULT31_BRANCH_NAMES[k] + '系升至 Lv' + r.newLevel + '，解锁「' + CULT31_BRANCH_LEVELS[k].levels[r.newLevel].unlock + '」');
      void before;
    }
    // 政策维护费每分钟从 funds 扣，不足时自动停用最贵的政策（不透支）。
    const pRaw = CultureV31Calculator.policyRawV31(this.activePolicies);
    if (pRaw.upkeep > 0) {
      if (this.funds >= pRaw.upkeep) { this.funds -= pRaw.upkeep; this.totalFundsSpent += pRaw.upkeep; }
      else {
        let worst = null; let worstUp = -1;
        for (const id of this.activePolicies) {
          for (const p of CULT31_POLICIES) if (p.id === id && p.upkeep > worstUp) { worstUp = p.upkeep; worst = p; }
        }
        if (worst) { this.setPolicyV31(game, worst.id, false); this.logV31('资金不足，自动停用政策「' + worst.name + '」'); }
      }
    }
    this._recomputeV31(game);
  }
  _dayTickV31(game) {
    // 每日结算：节日推进、名人薪资与忠诚、作品名气衰减、冲突检定与过期、里程碑、年度计数。
    const newYear = Math.floor(this.day / 360);
    if (newYear !== this._year) { this._year = newYear; this._festivalsThisYear = 0; this._largeFestivalsThisYear = 0; }
    for (const f of this.festivals) {
      const r = f.tickDayV31(this.day);
      if (r.changed && r.state === 'active') this.logV31('节日「' + f.name + '」开幕，全城加成生效');
      if (r.changed && r.state === 'done') {
        const def = CultureV31FestivalPlan.defOfV31(f.defId);
        if (def) this.branches[def.branch].addXpV31(20);
        this.branches[f.branch].festivalsHeld += 1;
        this.logV31('节日「' + f.name + '」落幕');
      }
    }
    let salaryTotal = 0;
    for (let i = this.celebs.length - 1; i >= 0; i--) {
      const c = this.celebs[i];
      c.dailyTickV31();
      salaryTotal += c.salary;
      const rc = c.raiseCheckV31(this._rng());
      if (rc.raise) this.logV31(c.name + '要求加薪至 ' + rc.newSalary + '/天（忠诚 ' + c.loyalty + '）');
    }
    if (salaryTotal > 0) {
      if (this.funds >= salaryTotal) { this.funds -= salaryTotal; this.totalFundsSpent += salaryTotal; }
      else {
        // 薪资不足：忠诚最低者离职一人（不透支、不欠薪）。
        let worstIdx = 0;
        for (let i = 1; i < this.celebs.length; i++) if (this.celebs[i].loyalty < this.celebs[worstIdx].loyalty) worstIdx = i;
        const gone = this.celebs.splice(worstIdx, 1)[0];
        if (gone) this.logV31('无力支付薪资，' + gone.name + '离职');
        if (this.funds >= salaryTotal) { this.funds -= salaryTotal; this.totalFundsSpent += salaryTotal; }
      }
    }
    for (const w of this.works) if (!w.venueId) w.decayFameV31(1);
    for (let i = this.conflicts.length - 1; i >= 0; i--) {
      const c = this.conflicts[i];
      if (!c.resolved && this.day >= c.expiresDay) {
        const r = c.autoResolveV31();
        this._applySatDeltaV31(game, r.sat);
        this.logV31('冲突「' + c.name + '」逾期未决，自动折中，满意度 −1');
      }
    }
    // 已解决冲突保留 7 天后清理（存档瘦身）。
    this.conflicts = this.conflicts.filter(function (c) { return !c.resolved || (this.day - c.day) < 7; }.bind(this));
    this.exhibitions = this.exhibitions.filter(function (e) { return this.day <= e.endDay; }.bind(this));
    this.rollConflictV31(game);
    this.checkMilestonesV31(game);
    if (this._pendingSatDays > 0) { this._pendingSatDays -= 1; if (this._pendingSatDays === 0) this._pendingSat = 0; }
    this._recomputeV31(game);
  }

  /* ---------- 面板数据（供 UI 读取，不写状态） ---------- */
  panelDataV31(game) {
    const r = this.computeCultureV31(game);
    return {
      version: CULT31_VERSION, day: this.day, funds: Math.round(this.funds),
      totalCulture: r.total, perBranch: r.perBranch, raw: r.raw,
      satBonus: r.satBonus, immMul: r.immMul, growthMul: r.growthMul, avgLevel: r.avgLevel,
      levels: this.levelsV31(),
      works: this.works.length, workSlots: this.workSlotsV31(),
      celebs: this.celebs.length, activeFestivals: this.festivals.filter(function (f) { return f.isActiveV31(); }).length,
      activePolicies: this.activePolicies.slice(), milestones: this.claimedMilestones.length,
      log: this.log.slice(-10),
    };
  }

  /* ---------- 存档 ---------- */
  saveV31() {
    return {
      version: CULT31_VERSION, day: this.day, funds: this.funds,
      totalFundsEarned: this.totalFundsEarned, totalFundsSpent: this.totalFundsSpent,
      branches: CULT31_BRANCH_IDS.map(function (k) { return this.branches[k].saveV31(); }.bind(this)),
      works: this.works.map(function (w) { return w.saveV31(); }),
      celebs: this.celebs.map(function (c) { return c.saveV31(); }),
      festivals: this.festivals.map(function (f) { return f.saveV31(); }),
      conflicts: this.conflicts.map(function (c) { return c.saveV31(); }),
      exhibitions: this.exhibitions.map(function (e) { return { defId: e.defId, endDay: e.endDay }; }),
      activePolicies: this.activePolicies.slice(),
      claimedMilestones: this.claimedMilestones.slice(),
      log: this.log.slice(-100),
      conflictCooldown: cult31DeepCloneV31(this._conflictCooldown),
      lastCelebEventDay: cult31DeepCloneV31(this._lastCelebEventDay || {}),
      largeFestivalsThisYear: this._largeFestivalsThisYear,
      year: this._year,
    };
  }
  loadV31(data) {
    if (!data) return false;
    this.day = cult31SafeNumV31(data.day, 0);
    this.funds = cult31SafeNumV31(data.funds, 200);
    this.totalFundsEarned = cult31SafeNumV31(data.totalFundsEarned, 0);
    this.totalFundsSpent = cult31SafeNumV31(data.totalFundsSpent, 0);
    if (Array.isArray(data.branches)) {
      for (const b of data.branches) if (b && this.branches[b.branch]) this.branches[b.branch].loadV31(b);
    }
    this.works = [];
    if (Array.isArray(data.works)) {
      for (const w of data.works) {
        const def = CultureV31WorkInstance.defOfV31(w.defId);
        if (!def) continue;
        const inst = new CultureV31WorkInstance(def, cult31SafeNumV31(w.score, def.baseScore), w.creatorCelebId);
        inst.loadV31(w);
        this.works.push(inst);
      }
    }
    this.celebs = [];
    if (Array.isArray(data.celebs)) {
      for (const c of data.celebs) {
        const def = CultureV31CelebrityInstance.defOfV31(c.defId);
        if (!def) continue;
        const inst = new CultureV31CelebrityInstance(def);
        inst.loadV31(c);
        this.celebs.push(inst);
      }
    }
    this.festivals = [];
    if (Array.isArray(data.festivals)) {
      for (const f of data.festivals) {
        const def = CultureV31FestivalPlan.defOfV31(f.defId);
        if (!def) continue;
        const inst = new CultureV31FestivalPlan(def, cult31SafeNumV31(f.startDay, 0));
        inst.loadV31(f);
        this.festivals.push(inst);
      }
    }
    this.conflicts = [];
    if (Array.isArray(data.conflicts)) {
      for (const c of data.conflicts) {
        const def = CultureV31ConflictInstance.defOfV31(c.defId);
        if (!def) continue;
        const inst = new CultureV31ConflictInstance(def, cult31SafeNumV31(c.day, 0));
        inst.loadV31(c);
        this.conflicts.push(inst);
      }
    }
    this.exhibitions = Array.isArray(data.exhibitions) ? data.exhibitions.filter(function (e) { for (const x of CULT31_EXHIBITIONS) if (x.id === e.defId) return true; return false; }).map(function (e) { return { defId: e.defId, endDay: cult31SafeNumV31(e.endDay, 0) }; }) : [];
    this.activePolicies = Array.isArray(data.activePolicies) ? data.activePolicies.filter(function (id) {
      for (const p of CULT31_POLICIES) if (p.id === id) return true;
      return false;
    }) : [];
    this.claimedMilestones = Array.isArray(data.claimedMilestones) ? data.claimedMilestones.slice() : [];
    this.log = Array.isArray(data.log) ? data.log.slice(-100) : [];
    this._conflictCooldown = data.conflictCooldown || {};
    this._lastCelebEventDay = data.lastCelebEventDay || {};
    this._largeFestivalsThisYear = cult31SafeNumV31(data.largeFestivalsThisYear, 0);
    this._year = cult31SafeNumV31(data.year, 0);
    this._rng = cult31MulberryV31(310731 + this.day);
    this._recomputeV31(null);
    return true;
  }
  serializeV31() { return JSON.stringify(this.saveV31()); }
  deserializeV31(json) {
    try { return this.loadV31(JSON.parse(json)); } catch (e) { return false; }
  }
}


/* ============================== CultureV31Integration：接入 ============================== */
/* 一行接入：CultureV31Integration.attach(game) */
/* 挂载：game.cultureV31（管理器）/ game.cultureV31Tick(game, now, dt) / */
/*   game.cultureV31Modifiers() / game.cultureV31Save() / game.cultureV31Load(data)。 */
/* game.js 主循环可调用 CultureV31Integration.tick(game, now, dt)； */
/* game.js 存档可在 save/load 数据中加 cultureV31: game.cultureV31Save()（本文件不改 game.js）。 */
const CultureV31Integration = {
  attach: function (game) {
    if (!game) return null;
    if (!game.cultureV31) game.cultureV31 = new CultureV31Manager();
    const mgr = game.cultureV31;
    game.cultureV31Tick = function (g, now, dt) { return mgr.tickV31(g || game, now, dt); };
    game.cultureV31Modifiers = function () { return mgr.getModifiersV31(game); };
    game.cultureV31Save = function () { return mgr.saveV31(); };
    game.cultureV31Load = function (data) { return mgr.loadV31(data); };
    return mgr;
  },
  tick: function (game, now, dt) {
    if (game && game.cultureV31) return game.cultureV31.tickV31(game, now, dt);
    return null;
  },
  version: CULT31_VERSION,
};

/* ============================== CultureV31SelfTest：自测 ============================== */
/* Node 自测：node /tmp/culture_v31_selftest.js（见生成器输出的自测脚本说明）。 */
/* 覆盖：公式复算、等级反查、创作/展览/节日/名人/冲突/存档往返、tick 推进。 */
const CultureV31SelfTest = {
  run: function () {
    const results = [];
    function ok(name, cond, detail) { results.push({ name: name, pass: !!cond, detail: detail || '' }); }
    // 公式：递减
    ok('diminish-0', CultureV31Calculator.diminishV31(0) === 0, 'raw=0 → 0');
    ok('diminish-100', Math.abs(CultureV31Calculator.diminishV31(100) - 93) < 0.01, 'raw=100 → 93.0，实算 ' + CultureV31Calculator.diminishV31(100));
    ok('diminish-400', Math.abs(CultureV31Calculator.diminishV31(400) - 330) < 0.01, 'raw=400 → 330.0');
    // 公式：等级反查
    ok('level-xp-0', CultureV31Calculator.levelFromXpV31(0) === 0, 'xp=0 → Lv0');
    ok('level-xp-80', CultureV31Calculator.levelFromXpV31(80) === 1, 'xp=80 → Lv1');
    ok('level-xp-340', CultureV31Calculator.levelFromXpV31(340) === 2, 'xp=340 → Lv2（80+260）');
    ok('level-xp-max', CultureV31Calculator.levelFromXpV31(999999) === 10, 'xp 极大 → Lv10');
    ok('xp-need-1', cult31XpNeedV31(1) === 80, 'need(1)=80');
    ok('xp-need-10', cult31XpNeedV31(10) === 4009, 'need(10)=4009，实算 ' + cult31XpNeedV31(10));
    // 公式：满意度 / 移民 / 增长
    ok('sat-cap', CultureV31Calculator.satisfactionBonusV31(10000, 0) === 25, '文化极大时满意度封顶 25');
    ok('sat-100', CultureV31Calculator.satisfactionBonusV31(100, 0) === 6, 'V=100 → +6.0');
    ok('imm-500', CultureV31Calculator.immigrationMulV31(500, 0) === 1.6, 'V=500 → 吸引力 1.6（封顶）');
    ok('imm-0', CultureV31Calculator.immigrationMulV31(0, 0) === 1, 'V=0 → 1.0');
    ok('growth-base', CultureV31Calculator.growthMulV31(0, 1) === 1, '平均 0 级、无吸引力 → 1.0');
    ok('growth-lv10', CultureV31Calculator.growthMulV31(10, 1.6) === 1.26, '平均 10 级、吸引力 1.6 → 1.26');
    // 公式：作品收益
    const wdef = CULT31_WORKS[0];
    const rev = CultureV31Calculator.workRevenueV31(wdef, 90, 1, 0);
    ok('work-rev-master', rev === Math.round(wdef.basePrice * 3.2), '大师档收益 = basePrice × 3.2，实算 ' + rev);
    // 数据规模
    ok('data-branches', Object.keys(CULT31_BRANCH_LEVELS).length === 5, '五系');
    ok('data-buildings', Object.keys(CULT31_BUILDING_CULTURE).length === 110, '建筑映射 110 座，实算 ' + Object.keys(CULT31_BUILDING_CULTURE).length);
    ok('data-policies', CULT31_POLICIES.length === 40, '政策 40 条');
    ok('data-works', CULT31_WORKS.length === 200, '作品 200 件，实算 ' + CULT31_WORKS.length);
    ok('data-festivals', CULT31_FESTIVALS.length === 36, '节日 36 个');
    ok('data-venues', CULT31_VENUES.length === 24, '场馆 24 座');
    ok('data-celebs', CULT31_CELEBRITIES.length === 110, '名人 110 位');
    ok('data-conflicts', CULT31_CONFLICTS.length + CULT31_CONFLICTS_X.length === 54, '冲突 54 起，实算 ' + (CULT31_CONFLICTS.length + CULT31_CONFLICTS_X.length));
    ok('data-milestones', CULT31_MILESTONES.length === 100, '里程碑 100 个');
    ok('data-tours', CULT31_TOURS.length === 24, '巡展 24 条');
    ok('data-exhibitions', CULT31_EXHIBITIONS.length === 48, '主题展览 48 个');
    ok('data-combos', CULT31_WORK_COMBOS.length === 120, '作品联动 120 组');
    ok('data-audience', CULT31_AUDIENCE_SEGMENTS.length === 20, '观众群体 20 类');
    ok('data-cevents', CULT31_CELEB_EVENTS.length === 60, '名人专场 60 场');
    ok('data-aftermath', CULT31_CONFLICT_AFTERMATH.length === 54, '冲突余波 54 条');
    ok('data-programs', CULT31_VENUE_PROGRAMS.length === 48, '场馆节目单 48 期');
    // 管理器：实例化与 tick
    const stubGame = {
      pop: { count: 120 },
      builder: { buildings: [{ id: 'library', level: 2 }, { id: 'stadium', level: 1 }, { id: 'park', level: 3 }] },
      player: { inv: { iron: 5000, steel: 2000, tech: 500, ice: 100, rare: 100, water: 100, food: 100, uranium: 10, he3: 5 } },
      policy: { active: [] },
      economy: { happiness: 70, balance: 10000 },
    };
    const mgr = new CultureV31Manager();
    ok('mgr-init', mgr.getModifiersV31(stubGame).cultureValue > 0, '初始文化值 > 0（图书馆 L2 + 体育场 + 公园），实算 ' + mgr.getModifiersV31(stubGame).cultureValue);
    const mods = mgr.getModifiersV31(stubGame);
    ok('mods-sat', mods.happinessAdd > 0 && mods.happinessAdd <= 40, '满意度加成在 (0,40]，实算 ' + mods.happinessAdd);
    ok('mods-imm', mods.immigrationMul >= 1 && mods.immigrationMul <= 2, '移民倍率在 [1,2]，实算 ' + mods.immigrationMul);
    ok('mods-growth', mods.growthMul >= 0.5 && mods.growthMul <= 2, '增长倍率在 [0.5,2]，实算 ' + mods.growthMul);
    const tickR = mgr.tickV31(stubGame, Date.now(), 60000);
    ok('tick-day', tickR.day === 1, 'tick 60000ms 推进 1 天，实算 day=' + tickR.day);
    ok('tick-xp', mgr.branches.art.xp > 0, 'tick 后艺术系经验 > 0，实算 ' + mgr.branches.art.xp);
    // 创作
    const c0 = mgr.createWorkV31(stubGame, 'cult31-work-001', null);
    ok('create-work', c0.ok === true && c0.score >= 0 && c0.score <= 100, '创作作品 001 成功，评分 ' + (c0.score === undefined ? '?' : c0.score));
    ok('create-cost-paid', stubGame.player.inv.iron < 5000, '创作扣了铁，剩余 ' + stubGame.player.inv.iron);
    // 展览（需场馆解锁：先把艺术系经验拉满到 Lv1）
    mgr.branches.art.addXpV31(10000);
    const ex = mgr.exhibitWorkV31(stubGame, 0, 'cult31-venue-01');
    ok('exhibit', ex.ok === true && ex.revenue > 0, '展览收益 > 0，实算 ' + (ex.revenue === undefined ? '?' : ex.revenue));
    // 节日
    const fest = mgr.planFestivalV31(stubGame, 'cult31-fest-01');
    ok('plan-fest', fest.ok === true, '筹办节日 01 成功' + (fest.ok ? '' : '：' + fest.reason));
    // 名人
    const rec = mgr.recruitCelebrityV31(stubGame, 'cult31-celeb-001');
    ok('recruit', rec.ok === true, '招募名人 001 成功' + (rec.ok ? '' : '：' + rec.reason));
    // 政策
    const pol = mgr.setPolicyV31(stubGame, 'cult31-pol-01', true);
    ok('policy-on', pol.ok === true, '激活政策 01 成功');
    // 冲突
    const confDef = CULT31_CONFLICTS[0];
    const conf = new CultureV31ConflictInstance(confDef, 1);
    const res = conf.resolveV31(0);
    ok('conflict-resolve', res.ok === true && res.sat !== undefined, '冲突抉择成功，满意度 ' + res.sat);
    // 存档往返
    const saved = mgr.saveV31();
    const mgr2 = new CultureV31Manager();
    const loaded = mgr2.loadV31(saved);
    ok('save-load', loaded === true && mgr2.works.length === mgr.works.length && mgr2.celebs.length === mgr.celebs.length, '存档往返：作品 ' + mgr2.works.length + ' 件，名人 ' + mgr2.celebs.length + ' 位');
    ok('save-load-funds', Math.abs(mgr2.funds - mgr.funds) < 0.01, '资金往返一致，' + mgr2.funds);
    // 接入
    const g2 = {};
    const attached = CultureV31Integration.attach(g2);
    ok('attach', attached !== null && g2.cultureV31 === attached && typeof g2.cultureV31Tick === 'function' && typeof g2.cultureV31Modifiers === 'function', 'attach 挂载 game.cultureV31 与方法齐全');
    const passed = results.filter(function (r) { return r.pass; }).length;
    return { total: results.length, passed: passed, failed: results.length - passed, results: results };
  },
};

/* ============================== 导出（Node / 浏览器两用） ============================== */
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    CULT31_VERSION: CULT31_VERSION, CULT31_BRANCH_IDS: CULT31_BRANCH_IDS,
    CULT31_BRANCH_LEVELS: CULT31_BRANCH_LEVELS, CULT31_BUILDING_CULTURE: CULT31_BUILDING_CULTURE,
    CULT31_POLICIES: CULT31_POLICIES, CULT31_WORKS: CULT31_WORKS, CULT31_FESTIVALS: CULT31_FESTIVALS,
    CULT31_VENUES: CULT31_VENUES, CULT31_CELEBRITIES: CULT31_CELEBRITIES,
    CULT31_CONFLICTS: CULT31_CONFLICTS, CULT31_CONFLICTS_X: CULT31_CONFLICTS_X,
    CULT31_MILESTONES: CULT31_MILESTONES, CULT31_BRANCH_SYNERGY: CULT31_BRANCH_SYNERGY,
    CULT31_TOURS: CULT31_TOURS, CULT31_EXHIBITIONS: CULT31_EXHIBITIONS,
    CULT31_WORK_COMBOS: CULT31_WORK_COMBOS, CULT31_AUDIENCE_SEGMENTS: CULT31_AUDIENCE_SEGMENTS,
    CULT31_CELEB_EVENTS: CULT31_CELEB_EVENTS, CULT31_CONFLICT_AFTERMATH: CULT31_CONFLICT_AFTERMATH,
    CULT31_VENUE_PROGRAMS: CULT31_VENUE_PROGRAMS,
    CULT31_WORK_REVENUE_TABLE: CULT31_WORK_REVENUE_TABLE,
    CULT31_CELEB_PROJECTION: CULT31_CELEB_PROJECTION,
    CultureV31Calculator: CultureV31Calculator, CultureV31BranchState: CultureV31BranchState,
    CultureV31WorkInstance: CultureV31WorkInstance, CultureV31CelebrityInstance: CultureV31CelebrityInstance,
    CultureV31FestivalPlan: CultureV31FestivalPlan, CultureV31ConflictInstance: CultureV31ConflictInstance,
    CultureV31Manager: CultureV31Manager, CultureV31Integration: CultureV31Integration,
    CultureV31SelfTest: CultureV31SelfTest,
    cult31XpNeedV31: cult31XpNeedV31, cult31LevelOutputV31: cult31LevelOutputV31,
  };
}
if (typeof window !== 'undefined') {
  window.CultureV31Integration = CultureV31Integration;
  window.CultureV31Manager = CultureV31Manager;
  window.CultureV31SelfTest = CultureV31SelfTest;
}

